package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.TlsClientCertificateBoundAccessTokensVO;

class TlsClientCertificateBoundAccessTokensValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of tls client certificate bound access tokens of oauth client")
  void test_tls_client_certificate_bound_access_tokens_value_holder_assign_plain_value() {
    Object holder = new Object();
    TlsClientCertificateBoundAccessTokensValueHolder<Object> value =
        new TlsClientCertificateBoundAccessTokensValueHolder<>(holder);
    Assertions.assertSame(holder, value.tlsClientCertificateBoundAccessTokens(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getTlsClientCertificateBoundAccessTokensValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getTlsClientCertificateBoundAccessTokens().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of tls client certificate bound access tokens of oauth client")
  void test_tls_client_certificate_bound_access_tokens_value_holder_assign_value_object() {
    Object holder = new Object();
    TlsClientCertificateBoundAccessTokensValueHolder<Object> value =
        new TlsClientCertificateBoundAccessTokensValueHolder<>(holder);
    TlsClientCertificateBoundAccessTokensVO vo = TlsClientCertificateBoundAccessTokensVO.from(true);
    Assertions.assertFalse(value.getTlsClientCertificateBoundAccessTokensValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.tlsClientCertificateBoundAccessTokens(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getTlsClientCertificateBoundAccessTokensValue().orElseThrow());
    Assertions.assertSame(holder, value.tlsClientCertificateBoundAccessTokens(Optional.empty()));
    Assertions.assertFalse(value.getTlsClientCertificateBoundAccessTokensValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.tlsClientCertificateBoundAccessTokens(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTlsClientCertificateBoundAccessTokensValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of tls client certificate bound access tokens of oauth client against the original")
  void test_tls_client_certificate_bound_access_tokens_value_holder_read() {
    Object holder = new Object();
    TlsClientCertificateBoundAccessTokensValueHolder<Object> value =
        new TlsClientCertificateBoundAccessTokensValueHolder<>(holder);
    TlsClientCertificateBoundAccessTokensVO vo = TlsClientCertificateBoundAccessTokensVO.from(true);
    TlsClientCertificateBoundAccessTokensVO other =
        TlsClientCertificateBoundAccessTokensVO.from(true);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getTlsClientCertificateBoundAccessTokensValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readTlsClientCertificateBoundAccessTokens(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readTlsClientCertificateBoundAccessTokens(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.tlsClientCertificateBoundAccessTokens(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo,
        value.readTlsClientCertificateBoundAccessTokens(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo,
        value.readTlsClientCertificateBoundAccessTokens(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of tls client certificate bound access tokens of oauth client")
  void test_tls_client_certificate_bound_access_tokens_value_holder_unset() {
    Object holder = new Object();
    TlsClientCertificateBoundAccessTokensValueHolder<Object> value =
        new TlsClientCertificateBoundAccessTokensValueHolder<>(holder);
    TlsClientCertificateBoundAccessTokensVO vo = TlsClientCertificateBoundAccessTokensVO.from(true);
    value.tlsClientCertificateBoundAccessTokens(vo);
    Assertions.assertSame(holder, value.unsetTlsClientCertificateBoundAccessTokensIfMatches(
        "tlsClientCertificateBoundAccessTokens_other"));
    Assertions.assertTrue(value.getTlsClientCertificateBoundAccessTokensValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTlsClientCertificateBoundAccessTokensIfMatches(
        "tlsClientCertificateBoundAccessTokens"));
    Assertions.assertFalse(value.getTlsClientCertificateBoundAccessTokensValue().isPresent(),
        "The field name must clear the value");
    value.tlsClientCertificateBoundAccessTokens(vo);
    Assertions.assertSame(holder, value.unsetTlsClientCertificateBoundAccessTokens());
    Assertions.assertFalse(value.getTlsClientCertificateBoundAccessTokensValue().isPresent(),
        "Unset must clear the value");
  }
}
